mapper.select:
SELECT DISTINCT a.*
FROM t_sys_menu a

    INNER JOIN t_sys_role_perms b ON b.permission_id = a.permission_id
    INNER JOIN t_sys_user_role c ON c.role_id = b.role_id

WHERE a.app_id = #{appId}
  AND a.enabled = true
  AND a.level IN (0, 1)

  AND c.user_id = #{userId}
  AND c.org_id = #{orgId}

ORDER BY a.level, a.sort, a.create_time
